def process_payment(user_id, amount, stripe_charge, calculate_fee, log_transaction):
    """Calls the Stripe API to charge a user and logs the transaction."""
    fee = calculate_fee(amount)
    charge = stripe_charge(user_id, amount)
    log_transaction(user_id, amount, fee, charge.id)
    return charge

